    crate::hybrid_retrieval::execute("search",validation)?;
    Ok(json!({"status":"READY","mode":"LEXICAL","graph_revision":projection["graph_revision"],"projection_receipt_sha256":projection["projection_receipt"]["projection_sha256"],"index_payload_sha256":hash(index)}))
